-- Glean durable catalog and isolated mock monitor state.
-- Logical associations are checked and locked by application transactions.
CREATE TABLE "glean_membership" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "paper_id" bigint NOT NULL, "topic" character varying NOT NULL, "original_id" character varying NOT NULL, "tier" character varying NOT NULL DEFAULT '', "primary_category" character varying NOT NULL DEFAULT '', "categories" jsonb NOT NULL, "dimensions" jsonb NOT NULL, "read_status" character varying NOT NULL DEFAULT 'unread', "source" character varying NOT NULL DEFAULT 'historical-baseline', "is_mock" boolean NOT NULL DEFAULT false, "raw" jsonb NOT NULL, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "created_by" bigint NULL, "updated_by" bigint NULL, PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "gleanmembership_topic_original_id" ON "glean_membership" ("topic", "original_id");
CREATE INDEX "gleanmembership_paper_id" ON "glean_membership" ("paper_id");
CREATE INDEX "gleanmembership_tier" ON "glean_membership" ("tier");
CREATE TABLE "glean_monitor_state" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "key" character varying NOT NULL, "snapshot" jsonb NOT NULL, "revision" bigint NOT NULL DEFAULT 0, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "created_by" bigint NULL, "updated_by" bigint NULL, PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "glean_monitor_state_key_key" ON "glean_monitor_state" ("key");
CREATE TABLE "glean_paper" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "identity_key" character varying NOT NULL, "title" character varying NOT NULL, "title_zh" text NOT NULL DEFAULT '', "abstract" text NOT NULL DEFAULT '', "authors" jsonb NOT NULL, "year" bigint NOT NULL DEFAULT 0, "venue" character varying NOT NULL DEFAULT '', "publication_type" character varying NOT NULL DEFAULT '', "doi" character varying NULL, "arxiv_id" character varying NULL, "url" text NOT NULL DEFAULT '', "formal_online_date" timestamptz NULL, "issue_date" timestamptz NULL, "date_provenance" text NOT NULL DEFAULT '', "evidence" jsonb NOT NULL, "is_mock" boolean NOT NULL DEFAULT false, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "created_by" bigint NULL, "updated_by" bigint NULL, PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "glean_paper_identity_key_key" ON "glean_paper" ("identity_key");
CREATE UNIQUE INDEX "glean_paper_doi_key" ON "glean_paper" ("doi");
CREATE UNIQUE INDEX "glean_paper_arxiv_id_key" ON "glean_paper" ("arxiv_id");
CREATE INDEX "gleanpaper_year_id" ON "glean_paper" ("year", "id");
CREATE INDEX "gleanpaper_venue" ON "glean_paper" ("venue");
CREATE INDEX "gleanpaper_formal_online_date_id" ON "glean_paper" ("formal_online_date", "id");
CREATE TABLE "glean_paper_state" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "paper_id" bigint NOT NULL, "user_id" bigint NOT NULL, "hidden" boolean NOT NULL DEFAULT false, "read_status" character varying NOT NULL DEFAULT 'unread', "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "created_by" bigint NULL, "updated_by" bigint NULL, PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "gleanpaperstate_user_id_paper_id" ON "glean_paper_state" ("user_id", "paper_id");
CREATE INDEX "gleanpaperstate_paper_id" ON "glean_paper_state" ("paper_id");
CREATE TABLE "glean_preference" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "user_id" bigint NOT NULL, "filters" jsonb NOT NULL, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "created_by" bigint NULL, "updated_by" bigint NULL, PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "glean_preference_user_id_key" ON "glean_preference" ("user_id");
CREATE TABLE "glean_venue" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "name" character varying NOT NULL, "kind" character varying NOT NULL DEFAULT 'journal', "jif" double precision NULL, "ccf" character varying NOT NULL DEFAULT '', "metric_year" bigint NOT NULL DEFAULT 0, "registry_version" character varying NOT NULL, "source" character varying NOT NULL DEFAULT '', "evidence" jsonb NOT NULL, "eligible_topics" jsonb NOT NULL, "qualification_status" character varying NOT NULL DEFAULT 'pending', "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "created_by" bigint NULL, "updated_by" bigint NULL, PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "gleanvenue_name_registry_version" ON "glean_venue" ("name", "registry_version");
